/**
 * Regenerates src/access/permissions.generated.ts from the backend's permission manifest.
 *
 * The manifest itself is generated by PermissionManifestTest in the backend repo, so a permission
 * code reaches this app only by existing on a real @PreAuthorize gate. Run after pulling backend
 * changes:
 *
 *   npm run sync:permissions
 *   PERMISSION_MANIFEST=/path/to/permission-manifest.json npm run sync:permissions
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const manifestPath =
  process.env.PERMISSION_MANIFEST ??
  resolve(here, '../../restaurant-saas/docs/contracts/permission-manifest.json')
const outPath = resolve(here, '../src/access/permissions.generated.ts')

let manifest
try {
  manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
} catch (error) {
  console.error(`Cannot read the permission manifest at:\n  ${manifestPath}\n`)
  console.error('Generate it in the backend repo with:')
  console.error('  ./mvnw test -Dtest=PermissionManifestTest\n')
  console.error('Or point at it explicitly with PERMISSION_MANIFEST=<path>.\n')
  console.error(error.message)
  process.exit(1)
}

const codes = manifest.permissions.map((entry) => entry.code).sort()
const roleRules = manifest.roleGates.map((entry) => entry.rule).sort()

if (codes.length === 0) {
  console.error('The manifest contains no permission codes — refusing to write an empty contract.')
  process.exit(1)
}

// Endpoint counts are the reason a code exists; keeping them in a comment makes a diff on this
// file readable ("EXPENSES_VOID lost its only endpoint") without opening the manifest.
const endpointCount = Object.fromEntries(
  manifest.permissions.map((entry) => [entry.code, entry.endpoints.length]),
)

const body = `// GENERATED by scripts/sync-permissions.mjs — do not edit.
// Source: the backend's docs/contracts/permission-manifest.json, itself generated from every
// @PreAuthorize gate. A code here is enforced by at least one endpoint.

/** Every permission code the backend actually enforces. */
export const PERMISSION_CODES = [
${codes.map((code) => `  '${code}', // ${endpointCount[code]} endpoint(s)`).join('\n')}
] as const

export type PermissionCode = (typeof PERMISSION_CODES)[number]

/**
 * Role rules the backend gates on directly, instead of a permission. These cannot be granted to a
 * user — they are a property of the role, so the UI must check \`roleCode\`, not \`permissions\`.
 */
export const ROLE_RULES = {
${roleRules.map((rule) => `  ${rule}: '${rule}',`).join('\n')}
} as const

export type RoleRule = keyof typeof ROLE_RULES
`

mkdirSync(dirname(outPath), { recursive: true })
writeFileSync(outPath, body)
console.log(`Wrote ${outPath}`)
console.log(`  ${codes.length} permission codes, ${roleRules.length} role rules`)
